48	/**
49	 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
50	 * publish these at their registrar so mail flows through the Nxeon mail server;
51	 * customers whose domain is inside Nxeon have this managed for them.
52	 */
53	const MAIL_HOST = "mail.nxeon.cloud";
54	const MAIL_MX_PRIORITY = 10;
55	// The mechanism that authorises our sending host; kept separate from the full
56	// record so the deliverability check can look for it inside whatever SPF the
57	// customer already publishes rather than demanding a byte-exact match.
58	const SPF_INCLUDE = "nxeon.cloud";
59	const SPF_VALUE = `v=spf1 include:${SPF_INCLUDE} ~all`;
60	const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
61	const DKIM_SELECTOR = "dkim";
62	
63	// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
64	const domainRe =
65	  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
66	
67	export type DnsRecord = {
68	  type: "TXT" | "MX";
69	  label: string; // human label for the row
70	  host: string; // record host / name
71	  value: string;
72	  priority?: number;
73	  note?: string;
74	};
75	
76	/**
77	 * Business Email — mailbox hosting per registered domain.
78	 *
79	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
80	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
81	 * which debits the wallet, then manages individual `Mailbox` rows under it.
82	 *
83	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
84	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
85	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
86	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
87	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
88	 * order flow; the row persists and can be retried via retryMailboxProvision.
89	 *
90	 * This module owns:
91	 *   - orderEmailHosting (customer subscribe)
92	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
93	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
94	 */
95	
96	type Result = { error?: string; ok?: boolean; warning?: string };
97	
98	/**
99	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
100	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
101	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
102	 * can be picked up once the integration is wired.
103	 */
104	async function provisionMailboxOnMailcow(mailbox: {
105	  id: string;
106	  address: string;
107	  quotaMB: number | null;
108	  subscription: { domainName: string };
109	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
110	  if (!mailcowConfigured()) return "PROVISIONING";
111	
112	  const [localPart] = mailbox.address.split("@");
113	  const domain = mailbox.subscription.domainName;
114	  const quotaMB = mailbox.quotaMB ?? 1024;
115	
116	  try {
117	    // Ensure the mail domain exists before adding the mailbox.
118	    if (!(await mcDomainExists(domain))) {
119	      // A concurrent create or pre-existing domain can still error here; ignore
120	      // and let the mailbox add be the real signal.
121	      await mcCreateDomain(domain).catch(() => {});
122	    }
123	
124	    const password = randomBytes(18).toString("base64url");
125	    await mcCreateMailbox({
126	      localPart,
127	      domain,
128	      name: mailbox.address,
129	      password,
130	      quotaMB,
131	    });
132	
133	    await db.mailbox.update({
134	      where: { id: mailbox.id },
135	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
136	    });
137	    return "ACTIVE";
138	  } catch (e) {
139	    await db.mailbox
140	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
141	      .catch(() => {});
142	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
143	    return "FAILED";
144	  }
145	}
146	
147	// ---------- Admin CRUD (billing area) ----------
148	
149	const planSchema = z.object({
150	  id: z.string().optional(),
151	  name: z.string().min(2).max(80),
152	  mailboxes: z.coerce.number().int().min(1).max(100000),
153	  storageGB: z.coerce.number().int().min(1).max(100000),
154	  priceCents: z.coerce.number().int().min(0).max(100000000),
155	  termMonths: z.coerce.number().int().min(1).max(36),
156	  sortOrder: z.coerce.number().int().min(0).max(100000),
157	});
158	
159	/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
160	export async function adminSaveEmailPlan(
161	  prev: Result | undefined,
162	  formData: FormData,
163	): Promise<Result> {
164	  const admin = await requireArea("billing");
165	
166	  const parsed = planSchema.safeParse({
167	    id: formData.get("id") || undefined,
168	    name: formData.get("name"),
169	    mailboxes: formData.get("mailboxes"),
170	    storageGB: formData.get("storageGB"),
171	    priceCents: formData.get("priceCents"),
172	    termMonths: formData.get("termMonths"),
173	    sortOrder: formData.get("sortOrder") ?? 0,
174	  });
175	  if (!parsed.success) {
176	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
177	  }
178	  const d = parsed.data;
179	  const active = formData.get("active") === "on";
180	
181	  const data = {
182	    name: d.name.trim(),
183	    mailboxes: d.mailboxes,
184	    storageGB: d.storageGB,
185	    priceCents: d.priceCents,
186	    termMonths: d.termMonths,
187	    active,
188	    sortOrder: d.sortOrder,
189	  };
190	
191	  if (d.id) {
192	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
193	    if (!existing) return { error: "Tier not found." };
194	    await db.emailPlan.update({ where: { id: d.id }, data });
195	  } else {
196	    await db.emailPlan.create({ data });
197	  }
198	
199	  await db.auditLog.create({
200	    data: {
201	      userId: admin.id,
202	      action: d.id ? "emailplan.update" : "emailplan.create",
203	      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
204	    },
205	  });
206	  revalidatePath("/admin/email-plans");
207	  return { ok: true };
208	}
209	
210	/** Flip a tier's active flag. */
211	export async function adminToggleEmailPlan(id: string): Promise<void> {
212	  const admin = await requireArea("billing");
213	  const plan = await db.emailPlan.findUnique({ where: { id } });
214	  if (!plan) return;
215	  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
216	  await db.auditLog.create({
217	    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
218	  });
219	  revalidatePath("/admin/email-plans");
220	}
221	
222	/** Delete a tier. Refused while subscriptions reference it. */
223	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
224	  const admin = await requireArea("billing");
225	  const plan = await db.emailPlan.findUnique({
226	    where: { id },
227	    include: { _count: { select: { subscriptions: true } } },
228	  });
229	  if (!plan) return { error: "Tier not found." };
230	  if (plan._count.subscriptions > 0) {
231	    return {
232	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
233	    };
234	  }
235	  await db.emailPlan.delete({ where: { id } });
236	  await db.auditLog.create({
237	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
238	  });
239	  revalidatePath("/admin/email-plans");
240	  return { ok: true };
241	}
242	
243	// ---------- Customer ordering ----------
244	
245	/**
246	 * Subscribe one of the caller's registered domains to an email plan. Validates
247	 * domain ownership + plan availability, then atomically debits the wallet and
248	 * creates the EmailSubscription with an expiry set from the plan term.
249	 *
250	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
251	 * provisioned with a mail provider yet — that integration is pending, and the
252	 * UI surfaces every mailbox as "provisioning" until it lands.
253	 */
254	export async function orderEmailHosting(
255	  domainName: string,
256	  emailPlanId: string,
257	  termMonthsRaw?: number,
258	  /**
259	   * "Apply my balance" — mirrors the VPS/hosting wizard toggle. Defaults ON (only an
260	   * explicit `false` turns it off) so existing callers keep applying the wallet first.
261	   * When the balance doesn't fully cover the term charge — the toggle is off, or the
262	   * balance is short — the remainder is charged to a card that funds the wallet, then
263	   * the wallet path (`orderEmailHostingCore`) places the subscription.
264	   */
265	  useWallet: boolean = true,
266	): Promise<Result | { checkout: EmbeddedCheckout }> {
267	  const user = await requireUser();
268	  // Spend path: block while an admin is impersonating, so support cannot buy a
269	  // subscription with a customer's wallet while acting as them.
270	  await assertNotImpersonating();
271	  // Purchase gate: an unverified address means we cannot reach the person we
272	  // are about to charge. See lib/email-verification.ts.
273	  const unverified = await emailVerificationError(user);
274	  if (unverified) return { error: unverified };
275	
276	  const name = String(domainName ?? "")
277	    .trim()
278	    .toLowerCase()
279	    .replace(/\.$/, "");
280	  if (!name) return { error: "Enter a domain." };
281	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
282	
283	  // Price the term for the wallet/card split. Business Email has no first-month-free,
284	  // so the amount due today IS the full term charge. Shared `emailChargeCents` with the
285	  // core below so the split and the debit can never use different formulas.
286	  const planForSplit = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
287	  if (!planForSplit || !planForSplit.active) return { error: "That email plan isn't available." };
288	  const term = normalizeProductTerm(termMonthsRaw);
289	  const { fullCharge } = await emailChargeCents(planForSplit, term);
290	  const { cardCents } = walletSplit({ dueCents: fullCharge, balanceCents: user.balanceCents, useWallet });
291	
292	  if (cardCents > 0) {
293	    // A card leg is due (the toggle is off, or the balance is short). Reject an already-
294	    // taken domain BEFORE opening a paid checkout (the core re-checks authoritatively at
295	    // fulfilment), then fund the remainder by card. On payment `fulfilCheckoutSession`
296	    // credits the card amount to the wallet and calls `orderEmailHostingCore`, which
297	    // debits the real charge — one debit path.
298	    const dupe = await db.emailSubscription.findFirst({ where: { domainName: name, status: { not: "CANCELLED" } } });
299	    if (dupe) {
300	      return {
301	        error:
302	          dupe.userId === user.id
303	            ? "This domain already has an email subscription."
304	            : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
305	      };
306	    }
307	    const checkout = await createEmailOrderCheckout(user, cardCents, { domainName: name, emailPlanId, termMonths: term });
308	    if (!checkout) return { error: "Card payments aren't set up yet — top up your wallet first." };
309	    return { checkout };
310	  }
311	
312	  // cardCents <= 0 → the wallet covers the term charge. EXISTING wallet path, unchanged.
313	  return orderEmailHostingCore(user, name, emailPlanId, termMonthsRaw);
314	}
315	
316	/** Term price for an email plan, in ONE place shared by the split pre-check and the
317	 *  authoritative debit (`orderEmailHostingCore`). `emailMonthlyBaseCents` is the plan's
318	 *  monthly base (seeded plans are monthly, so it is just `priceCents`). */
319	async function emailChargeCents(
320	  plan: Parameters<typeof emailMonthlyBaseCents>[0],
321	  term: number,
322	): Promise<{ annualPct: number; fullCharge: number }> {
323	  const annualPct = await annualDiscountPct();
324	  const fullCharge = termPriceCents(emailMonthlyBaseCents(plan), term, annualPct);
325	  return { annualPct, fullCharge };
326	}
327	
328	/**
329	 * The wallet-charging placement core, WITHOUT the auth/split preamble — takes the
330	 * already-loaded `user` explicitly so it runs from BOTH the interactive action
331	 * (`orderEmailHosting`, wallet path) and the card-funded fulfilment path
332	 * (`placeEmailCardOrder` → `fulfilCheckoutSession`). Everything below — the domain
333	 * dupe guard, pricing, the wallet debit and the subscription create — is byte-for-byte
334	 * the wallet-only logic that used to live inline in `orderEmailHosting`.
335	 */
336	async function orderEmailHostingCore(
337	  user: User,
338	  domainName: string,
339	  emailPlanId: string,
340	  termMonthsRaw?: number,
341	): Promise<Result> {
342	  const name = String(domainName ?? "")
343	    .trim()
344	    .toLowerCase()
345	    .replace(/\.$/, "");
346	  if (!name) return { error: "Enter a domain." };
347	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
348	
349	  // Is the domain registered inside Nxeon? If so we control its DNS and can
350	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
351	  // verified via DNS before mail flows.
352	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
353	  const external = !inAccount;
354	
355	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
356	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
357	
358	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
359	  //
360	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
361	  // which let anyone buy a subscription for a domain another customer already
362	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
363	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
364	  // ADDRESS — so an attacker could create admin@victim.com under their own
365	  // subscription, call resetMailboxPassword() (which passes its ownership check
366	  // because the row is theirs), and have the password of the victim's real, live
367	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
368	  const dupe = await db.emailSubscription.findFirst({
369	    where: { domainName: name, status: { not: "CANCELLED" } },
370	  });
371	  if (dupe) {
372	    return {
373	      error:
374	        dupe.userId === user.id
375	          ? "This domain already has an email subscription."
376	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
377	    };
378	  }
379	
380	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
381	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
382	  // strikethrough shown on the pricing page is the real renewal price and this
383	  // discounted value is the real first-term price — displayed === charged.
384	  // Managed first-month-free. `promoCharge` mirrors the pre-existing behaviour
385	  // (the first term is free); `fullCharge` is the plan price. The credit is granted
386	  // ONLY if the atomic claim inside the charge tx succeeds — otherwise (already
387	  // redeemed by this account/IP, or the promo is off) the subscription is created
388	  // at FULL price. The eligibility pre-check only picks the balance gate so a
389	  // first-time, $0-balance customer can still subscribe free.
390	  // First-month-free is scoped to Shared Web Hosting only — Business Email always
391	  // bills full. firstMonthFreeAppliesTo("EMAIL") is false, so promoEnabled is false.
392	  const promoEnabled = firstMonthFreeAppliesTo("EMAIL") && (await firstMonthFreeEnabled());
393	  const campaign = promoCampaignFromCookie(await cookies());
394	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
395	  // Billing term (Monthly / Annual). The annual rate is resolved ONCE, frozen onto
396	  // the subscription, charged up front and read back at renewal — displayed ===
397	  // charged === renewed. `emailMonthlyBaseCents` is the plan's monthly base (every
398	  // seeded plan is monthly, so it is just `priceCents`).
399	  const term = normalizeProductTerm(termMonthsRaw);
400	  const { annualPct, fullCharge } = await emailChargeCents(plan, term);
401	  // Business Email is NOT a first-month-free product (firstMonthFreeAppliesTo("EMAIL")
402	  // is false), so this stays the full term charge — kept for parity with the other flows.
403	  const promoCharge = 0;
404	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
405	  const anticipated = eligible ? promoCharge : fullCharge;
406	  if (user.balanceCents < anticipated) {
407	    return { error: "Insufficient balance. Top up your wallet first." };
408	  }
409	
410	  // Captured out of the charge tx for the post-commit invoice document (Fix A).
411	  let debitedCents = 0;
412	  try {
413	    await db.$transaction(async (tx) => {
414	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
415	      let debitCents = fullCharge;
416	      let promoClaimId: string | null = null;
417	      if (promoEnabled) {
418	        const claim = await claimFirstMonthFree(tx, {
419	          userId: user.id,
420	          ipHash,
421	          serviceType: "EMAIL",
422	          campaign,
423	          chargedCents: promoCharge,
424	        });
425	        if (claim.claimed) {
426	          debitCents = promoCharge;
427	          promoClaimId = claim.id;
428	        }
429	      }
430	      const note = debitCents < fullCharge ? " — First month free" : "";
431	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
432	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
433	      await debitWallet(tx, user.id, debitCents);
434	      debitedCents = debitCents;
435	      await tx.walletTransaction.create({
436	        data: {
437	          userId: user.id,
438	          amountCents: -debitCents,
439	          description: `Business Email: ${plan.name} for ${name} — ${termLabel}${note}`,
440	        },
441	      });
442	      const sub = await tx.emailSubscription.create({
443	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
444	        // `annualDiscountPct` on EmailSubscription until regenerated at deploy.
445	        data: {
446	          userId: user.id,
447	          domainName: name,
448	          emailPlanId: plan.id,
449	          status: "ACTIVE",
450	          autoRenew: true,
451	          // The term the customer chose, and the annual rate frozen at sale, so the
452	          // renewal sweep bills the SAME price it was ordered at.
453	          termMonths: term,
454	          annualDiscountPct: annualPct,
455	          expiresAt: addMonths(new Date(), term),
456	          // In-account domains: we control DNS, so treat as verified now. External
457	          // domains: not verified until the customer publishes DNS + we confirm it.
458	          external,
459	          verified: !external,
460	          verifiedAt: external ? null : new Date(),
461	          verifyToken: external ? randomBytes(24).toString("hex") : null,
462	        } as Prisma.EmailSubscriptionUncheckedCreateInput,
463	      });
464	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, sub.id, debitCents);
465	    });
466	  } catch (e) {
467	    if (e instanceof InsufficientBalanceError) {
468	      return { error: "Insufficient balance. Top up your wallet first." };
469	    }
470	    throw e;
471	  }
472	
473	  await db.auditLog.create({
474	    data: {
475	      userId: user.id,
476	      action: "emailhosting.order",
477	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
478	    },
479	  });
480	
481	  // Fix A — the itemised invoice DOCUMENT + its emailed PDF for a business-email
482	  // order. Fires here in the CORE placement fn, so it runs exactly once for BOTH the
483	  // wallet path (orderEmailHosting) and the card path (placeEmailCardOrder →
484	  // fulfilCheckoutSession → here). Post-commit and fully best-effort: the wallet has
485	  // already been debited, so a mail/invoice failure must NEVER surface as an order
486	  // failure. Business Email is untaxed and never first-month-free, so the amount is
487	  // the real debited cents (the full term charge).
488	  try {
489	    const invTermLabel = vpsTerm(term).label;
490	    const invDesc = `Business Email: ${plan.name} for ${name} — ${invTermLabel}`;
491	    const createdInvoice = await db.invoice.create({
492	      data: invoiceCreateData({
493	        userId: user.id,
494	        description: invDesc,
495	        status: "PAID",
496	        taxCents: 0,
497	        taxRatePercent: 0,
498	        taxCountry: null,
499	        period: { start: new Date(), end: addMonths(new Date(), term) },
500	        lineItems: [{ description: invDesc, qty: 1, unitCents: debitedCents, amountCents: debitedCents }],
501	      }),
502	    });
503	    const { sendMail, emails } = await import("./mailer");
504	    const branding = await invoiceBranding();
505	    const tpl = emails.invoiceNew(
506	      {
507	        invoiceNumber: formatInvoiceNumber(createdInvoice.number, branding.numberPrefix),
508	        amount: `$${(createdInvoice.amountCents / 100).toFixed(2)}`,
509	        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
510	        description: invDesc,
511	      },
512	      true, // the itemised PDF is attached (invoiceId passed below)
513	    );
