646	/**
647	 * Verify that an EXTERNAL domain's owner has published our verification record.
648	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
649	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
650	 * corroboration. The result is derived entirely server-side from live DNS —
651	 * client input never decides the outcome. Rate-limited per user + subscription.
652	 */
653	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
654	  const user = await requireUser();
655	
656	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
657	  if (!sub) return { error: "Subscription not found." };
658	  if (sub.userId !== user.id) return { error: "Not your subscription." };
659	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
660	  if (sub.verified) return { ok: true };
661	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
662	
663	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
664	    max: 6,
665	    windowMs: 60_000,
666	  });
667	  if (!rl.ok) {
668	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
669	  }
670	
671	  const domain = sub.domainName;
672	  const expected = `nxeon-verify=${sub.verifyToken}`;
673	
674	  // Primary signal: the verification TXT record must contain our exact token.
675	  let tokenFound = false;
676	  try {
677	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
678	    // Each record may be split into multiple strings — join per-record chunks.
679	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
680	  } catch {
681	    tokenFound = false;
682	  }
683	
684	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
685	  let mxOk = false;
686	  try {
687	    const mx = await resolveMx(domain);
688	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
689	  } catch {
690	    mxOk = false;
691	  }
692	
693	  if (!tokenFound) {
694	    return {
695	      error: mxOk
696	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
697	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
698	    };
699	  }
700	
701	  await db.emailSubscription.update({
702	    where: { id: sub.id },
703	    data: { verified: true, verifiedAt: new Date() },
704	  });
705	
706	  await db.auditLog.create({
707	    data: {
708	      userId: user.id,
709	      action: "emailhosting.verify",
710	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
711	    },
712	  });
713	  revalidatePath("/dashboard/email");
714	  return { ok: true };
715	}
