719	/**
720	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
721	 *
722	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
723	 * product — the platform owner hit exactly this and had to reach for an external
724	 * tool. This returns pass/fail per record with the value actually observed beside
725	 * the expected one, so the customer can see which DNS row is wrong.
726	 *
727	 * Two correctness rules this depends on:
728	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
729	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
730	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
731	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
732	 *     a write-once cache that can outlive a key rotation.
733	 *
734	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
735	 */
736	export async function checkEmailDeliverability(
737	  subscriptionId: string,
738	): Promise<{ error?: string; report?: DeliverabilityReport }> {
739	  const user = await requireUser();
740	
741	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
742	  if (!sub) return { error: "Subscription not found." };
743	  if (sub.userId !== user.id) return { error: "Not your subscription." };
744	  // A cancelled subscription's domain may since have been taken by another
745	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
746	  // rows), so the old owner must not keep a live probe pointed at it.
747	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
748	
749	  // NOTE on domain verification: this check deliberately does NOT require
750	  // `sub.verified`, unlike every action that changes mail routing. It only READS
751	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
752	  // domain is precisely the case a customer needs it for — gating it would hide
753	  // the diagnosis exactly when the records are wrong. Ownership of the
754	  // subscription is still required so the panel can't be used to scan arbitrary
755	  // domains through our server.
756	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
757	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
758	
759	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
760	  // silently comparing against a cached value that may no longer sign anything.
761	  let dkim: { selector: string; txt: string } | null = null;
762	  if (mailcowConfigured()) {
763	    try {
764	      const live = await mcGetDkimDetails(sub.domainName);
765	      if (live) dkim = { selector: live.selector, txt: live.txt };
766	    } catch (e) {
767	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
768	    }
769	  }
770	
771	  try {
772	    const report = await checkDeliverability({
773	      domain: sub.domainName,
774	      mailHost: MAIL_HOST,
775	      spfInclude: SPF_INCLUDE,
776	      spfExpected: SPF_VALUE,
777	      dmarcExpected: DMARC_VALUE,
778	      dkim,
779	    });
780	    return { report };
781	  } catch (e) {
782	    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
783	    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
784	  }
785	}
