790	/**
791	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
792	 * quota and address uniqueness within the subscription, records the intended
793	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
794	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
795	 */
796	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
797	  const user = await requireUser();
798	
799	  const sub = await db.emailSubscription.findUnique({
800	    where: { id: subscriptionId },
801	    include: { emailPlan: true, mailboxes: true },
802	  });
803	  if (!sub) return { error: "Subscription not found." };
804	  if (sub.userId !== user.id) return { error: "Not your subscription." };
805	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
806	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
807	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
808	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
809	  // mailbox minted here acts on that domain's real mail. An external domain must
810	  // prove control via DNS before it can mint a single address, so even if a
811	  // duplicate subscription is ever created again this cannot be weaponised.
812	  if (sub.external && !sub.verified) {
813	    return {
814	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
815	    };
816	  }
817	
818	  const local = String(localPart ?? "").trim().toLowerCase();
819	  if (!localPartRe.test(local) || local.length > 64) {
820	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
821	  }
822	
823	  const address = `${local}@${sub.domainName}`;
824	
825	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
826	    return {
827	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
828	    };
829	  }
830	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
831	    return { error: "That address already exists." };
832	  }
833	
834	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
835	  const quotaMB = sub.emailPlan.storageGB * 1024;
836	
837	  const mailbox = await db.mailbox.create({
838	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
839	  });
840	
841	  await db.auditLog.create({
842	    data: { userId: user.id, action: "mailbox.add", detail: address },
843	  });
844	
845	  // Additive, failure-tolerant provisioning — never throws out of the flow.
846	  await provisionMailboxOnMailcow({
847	    id: mailbox.id,
848	    address: mailbox.address,
849	    quotaMB,
850	    subscription: { domainName: sub.domainName },
851	  });
852	
853	  revalidatePath("/dashboard/email");
854	  return { ok: true };
855	}
