904	/** Remove a mailbox the caller owns (via its subscription). */
905	export async function removeMailbox(mailboxId: string): Promise<Result> {
906	  const user = await requireUser();
907	
908	  const mailbox = await db.mailbox.findUnique({
909	    where: { id: mailboxId },
910	    include: { subscription: true },
911	  });
912	  if (!mailbox) return { error: "Mailbox not found." };
913	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
914	
915	  // Delete on Mailcow BEFORE dropping our row — and distinguish the two failure
916	  // modes, because they demand opposite actions:
917	  //
918	  //   - Mailcow REFUSED (reachable, returned an error): the mail server and our
919	  //     database disagree about this mailbox. Deleting our row here would leave a
920	  //     LIVE mailbox still receiving the customer's mail with no record of it in
921	  //     the product — silent data loss. Surface the error and keep the row.
922	  //   - Mailcow UNREACHABLE (transport failure): the server may just be down.
923	  //     Blocking removal forever on an outage is wrong, so we drop our row and
924	  //     tell the customer the mailbox itself may still exist and to retry once
925	  //     mail service is back.
926	  //
927	  // The previous `.catch(() => {})` collapsed both into "deleted, ok:true" — the
928	  // worse answer in every case.
929	  let mailcowUnreachable = false;
930	  if (mailcowConfigured()) {
931	    try {
932	      await mcDeleteMailbox(mailbox.address);
933	    } catch (e) {
934	      if (isMailcowUnreachable(e)) {
935	        mailcowUnreachable = true;
936	        console.warn(`[mailcow] delete ${mailbox.address}: unreachable, removing local record anyway:`, e);
937	      } else {
938	        console.error(`[mailcow] delete ${mailbox.address} REFUSED:`, e);
939	        return {
940	          error:
941	            "The mail server wouldn't remove this mailbox, so we've left it in place rather than lose your mail. Please try again in a moment, or contact support if it keeps happening.",
942	        };
943	      }
944	    }
945	  }
946	
947	  await db.mailbox.delete({ where: { id: mailbox.id } });
948	
949	  await db.auditLog.create({
950	    data: {
951	      userId: user.id,
952	      action: "mailbox.remove",
953	      detail: mailcowUnreachable ? `${mailbox.address} (mailcow unreachable — server-side delete not confirmed)` : mailbox.address,
954	    },
955	  });
956	  revalidatePath("/dashboard/email");
957	  return mailcowUnreachable
958	    ? {
959	        ok: true,
960	        warning:
961	          "Removed from your account. The mail server was unreachable, so the mailbox itself may still exist — it will be cleared when mail service is back, or contact support if messages keep arriving.",
962	      }
963	    : { ok: true };
964	}
