1001	
1002	  await db.mailbox.update({
1003	    where: { id: mailbox.id },
1004	    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
1005	  });
1006	
1007	  await db.auditLog.create({
1008	    data: {
1009	      userId: user.id,
1010	      action: suspended ? "mailbox.suspend" : "mailbox.resume",
1011	      detail: mailbox.address,
1012	    },
1013	  });
1014	  revalidatePath("/dashboard/email");
1015	  return mailcowUnreachable
1016	    ? {
1017	        ok: true,
1018	        warning: `Updated in your account, but the mail server was unreachable so it may not be ${suspended ? "suspended" : "active"} yet — it will reconcile when mail service is back.`,
1019	      }
