  // Bundled email mailboxes included with the plan. -1 = unlimited. Provisioned
  // on our own Nxeon Mail (Mailcow) backend when the account is created.
  mailboxes     Int              @default(1)
  // Marketing flags surfaced on the plan cards.
  freeMigration Boolean          @default(false) // "we move your existing site free"
  featured      Boolean          @default(false) // "Most popular" highlight
