/** Anything that carries a `promoRedemption` delegate — the client or a tx client. */
type PromoClient = Prisma.TransactionClient | typeof db;

/** The one place the stale-client cast lives. */
function promoDelegate(client: PromoClient): PromoDelegate {
  return (client as unknown as { promoRedemption: PromoDelegate }).promoRedemption;
}

/** Is the sitewide first-month-free offer switched on? (Owner toggle.) */
export async function firstMonthFreeEnabled(): Promise<boolean> {
  // Imported lazily so this module stays importable from the worker (no request
  // scope) without dragging server-only settings wiring into every consumer.
  const { getSettingBool } = await import("./settings");
  return getSettingBool("first_month_free_enabled", true);
}

/**
 * Which products the first-month-free promo is granted on. Owner decision
 * (2026-08-11): **Shared Web Hosting ONLY**. A free month of a $2.99–$8.99
 * hosting plan is a cheap acquisition offer for the first paid ad channel;
 * a free month of a $6.49–$32.99 VPS (or a game/email plan) is real exposure.
 * VPS / EMAIL / GAME always bill full. To extend the promo to another product
 * later, add its PromoServiceType here — every order flow reads this one gate,
 * so nothing else changes.
 */
export const FIRST_MONTH_FREE_SERVICES: PromoServiceType[] = ["HOSTING"];

/** Does the first-month-free promo apply to this product? (See above.) */
export function firstMonthFreeAppliesTo(service: PromoServiceType): boolean {
  return FIRST_MONTH_FREE_SERVICES.includes(service);
