145	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
146	  }
147	
148	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
149	  const guardKey = `register:${user.id}:${domain}`;
150	  if (!beginSubmit(guardKey)) {
151	    return { error: "That registration is already being processed — give it a moment before retrying." };
152	  }
153	
154	  try {
155	    const existing = await db.domain.findUnique({ where: { name: domain } });
156	    if (existing) {
157	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
158	      if (existing.status === "PENDING") {
159	        return { error: "You already have a registration in progress for this domain." };
160	      }
161	      return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
162	    }
163	
164	    // Live availability + retail(markup) & cost prices from name.com
165	    let priceCents: number; // retail per year (customer)
166	    let costCents: number; // registrar cost per year (us)
167	    try {
168	      const [check] = await checkDomains([domain]);
169	      if (!check) return { error: "Could not check availability. Try again." };
170	      if (!check.available) return { error: "Domain is not available." };
171	      if (check.premium) return { error: "Premium domains are not supported yet." };
172	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
173	      priceCents = check.priceCents;
174	      costCents = check.costCents;
175	    } catch (e: any) {
176	      return { error: String(e?.message ?? e).slice(0, 200) };
177	    }
178	
179	    const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
180	    const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
181	    if (user.balanceCents < totalCents) {
182	      return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
183	    }
184	
185	    let record;
186	    try {
187	      record = await db.$transaction(async (tx) => {
188	        // Re-check inside the transaction: the availability round-trip above is
189	        // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
190	        // even if this read misses, the create below rolls the whole debit back.
191	        const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
192	        if (dupe) throw new DuplicateDomainError();
193	        await debitWallet(tx, user.id, totalCents);
194	        await tx.walletTransaction.create({
195	          data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
196	        });
197	        return tx.domain.create({
198	          data: {
199	            name: domain,
200	            userId: user.id,
201	            priceCents,
202	            costCents,
203	            termYears: dTerm.years,
204	            status: "PENDING",
205	            registrar: "name.com",
206	            partnerSource: partnerSource ?? null,
207	          },
208	        });
209	      });
210	    } catch (e) {
211	      if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
212	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
213	        return { error: "This domain is already being registered — you have not been charged twice." };
214	      }
215	      throw e;
216	    }
217	
218	    try {
219	      const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
220	      const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
221	      await db.domain.update({
222	        where: { id: record.id },
223	        data: {
224	          status: "ACTIVE",
225	          registeredAt: new Date(),
226	          expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
227	        },
228	      });
229	      await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
230	      await db.notification.create({
231	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
232	      });
233	      // Tell the partner (best-effort, never blocks the order) — only for orders
234	      // tagged via a partner deep link. Most domain registrations are direct Nxeon
235	      // customers and must never be forwarded to a partner's webhook.
236	      if (partnerSource === "kodely") {
237	        await notifyPartner("domain.registered", { userId: user.id, domain, expiresAt: info.expires ?? null });
238	      }
239	    } catch (e: any) {
240	      const reason = String(e?.message ?? e).slice(0, 400);
241	      // NEVER refund blind: a timeout/5xx often means the order DID go through.
242	      const verdict = await verifyRegistration(domain);
243	
244	      if (verdict.state === "registered") {
245	        // The registration exists — keep the charge and finish the record.
246	        await db.domain.update({
247	          where: { id: record.id },
248	          data: {
249	            status: "ACTIVE",
250	            registeredAt: new Date(),
251	            expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
252	            error: `Recovered after registrar error: ${reason}`.slice(0, 500),
253	          },
254	        });
255	        await db.auditLog.create({
256	          data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
257	        });
258	        await db.notification.create({
259	          data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
260	        });
261	        redirect(`/dashboard/domains/${record.id}`);
262	      }
263	
264	      if (verdict.state === "not-registered") {
265	        // Confirmed still available at the registrar — refunding is safe.
266	        await db.$transaction([
267	          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
268	          db.walletTransaction.create({
269	            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
270	          }),
271	          db.domain.update({
272	            where: { id: record.id },
273	            data: { status: "FAILED", error: reason.slice(0, 500) },
274	          }),
275	        ]);
276	        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
277	      }
278	
279	      // Unknown: leave PENDING and charged, flag for manual review. Refunding
280	      // here risks giving away a domain we actually paid the registrar for.
281	      await db.domain.update({
282	        where: { id: record.id },
283	        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
284	      });
285	      await db.auditLog.create({
286	        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
287	      });
