289	        data: {
290	          userId: user.id,
291	          title: `Domain ${domain} needs review`,
292	          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
293	          href: `/dashboard/domains/${record.id}`,
294	        },
295	      });
296	      return {
297	        error:
298	          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
299	          `It is marked for review — do not retry, you will not be charged twice.`,
300	      };
301	    }
302	    redirect(`/dashboard/domains/${record.id}`);
303	  } finally {
